{

"kind": "propose",
"summary": "Increase probe timeouts to match application response times",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness and readiness probes timeout before application responds",
    "supporting": ["probe_timeouts", "ev-target_events", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search-api",
    "uid": "uid-deployment-search-api"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    },
    "readiness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Probes will wait longer for application responses, preventing false timeouts",
  "rationale": "Logs show application responds to /ready and /healthz within 5 seconds, but probes timeout after 1s. Increasing timeouts to 5s aligns with actual response times.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-rollout_history"],
  "cited_predicates": ["probe_timeouts", "probe_kills"]
}
}
